//
//
//     com.fasterxml.jackson.core     : jackson-databind          : 2.9.0
//     com.fasterxml.jackson.datatype : jackson-datatype-jsr310   : 2.9.0
//
// Import this package:
//
//     import io.quicktype.Converter;
//
// Then you can deserialize a JSON string with
//
//     TopLevel data = Converter.TopLevelFromJsonString(jsonString);
//     List<String> data = Converter.LabelsFromJsonString(jsonString);
//     Status data = Converter.StatusFromJsonString(jsonString);

package io.quicktype;

import java.io.IOException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import java.util.*;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.OffsetTime;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.temporal.ChronoField;

public class Converter {
    // Date-time helpers

    private static final DateTimeFormatter DATE_TIME_FORMATTER = new DateTimeFormatterBuilder()
            .appendOptional(DateTimeFormatter.ISO_DATE_TIME)
            .appendOptional(DateTimeFormatter.ISO_OFFSET_DATE_TIME)
            .appendOptional(DateTimeFormatter.ISO_INSTANT)
            .appendOptional(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SX"))
            .appendOptional(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ssX"))
            .appendOptional(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
            .toFormatter()
            .withZone(ZoneOffset.UTC);

    public static OffsetDateTime parseDateTimeString(String str) {
        return ZonedDateTime.from(Converter.DATE_TIME_FORMATTER.parse(str)).toOffsetDateTime();
    }

    private static final DateTimeFormatter TIME_FORMATTER = new DateTimeFormatterBuilder()
            .appendOptional(DateTimeFormatter.ISO_TIME)
            .appendOptional(DateTimeFormatter.ISO_OFFSET_TIME)
            .parseDefaulting(ChronoField.YEAR, 2020)
            .parseDefaulting(ChronoField.MONTH_OF_YEAR, 1)
            .parseDefaulting(ChronoField.DAY_OF_MONTH, 1)
            .toFormatter()
            .withZone(ZoneOffset.UTC);

    public static OffsetTime parseTimeString(String str) {
        return ZonedDateTime.from(Converter.TIME_FORMATTER.parse(str)).toOffsetDateTime().toOffsetTime();
    }
    // Serialize/deserialize helpers

    public static TopLevel TopLevelFromJsonString(String json) throws IOException {
        return getTopLevelObjectReader().readValue(json);
    }

    public static String TopLevelToJsonString(TopLevel obj) throws JsonProcessingException {
        return getTopLevelObjectWriter().writeValueAsString(obj);
    }

    public static List<String> LabelsFromJsonString(String json) throws IOException {
        return getLabelsObjectReader().readValue(json);
    }

    public static String LabelsToJsonString(List<String> obj) throws JsonProcessingException {
        return getLabelsObjectWriter().writeValueAsString(obj);
    }

    public static Status StatusFromJsonString(String json) throws IOException {
        return getStatusObjectReader().readValue(json);
    }

    public static String StatusToJsonString(Status obj) throws JsonProcessingException {
        return getStatusObjectWriter().writeValueAsString(obj);
    }

    private static ObjectReader TopLevelReader;
    private static ObjectWriter TopLevelWriter;

    private static void instantiateTopLevelMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.findAndRegisterModules();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
        mapper.configure(DeserializationFeature.ACCEPT_FLOAT_AS_INT, false);
        mapper.configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);
        SimpleModule module = new SimpleModule();
        module.addDeserializer(OffsetDateTime.class, new JsonDeserializer<OffsetDateTime>() {
            @Override
            public OffsetDateTime deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JsonProcessingException {
                String value = jsonParser.getText();
                return Converter.parseDateTimeString(value);
            }
        });
        mapper.registerModule(module);
        TopLevelReader = mapper.readerFor(TopLevel.class);
        TopLevelWriter = mapper.writerFor(TopLevel.class);
    }

    private static ObjectReader getTopLevelObjectReader() {
        if (TopLevelReader == null) instantiateTopLevelMapper();
        return TopLevelReader;
    }

    private static ObjectWriter getTopLevelObjectWriter() {
        if (TopLevelWriter == null) instantiateTopLevelMapper();
        return TopLevelWriter;
    }

    private static ObjectReader LabelsReader;
    private static ObjectWriter LabelsWriter;

    private static void instantiateLabelsMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.findAndRegisterModules();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
        mapper.configure(DeserializationFeature.ACCEPT_FLOAT_AS_INT, false);
        mapper.configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);
        SimpleModule module = new SimpleModule();
        module.addDeserializer(OffsetDateTime.class, new JsonDeserializer<OffsetDateTime>() {
            @Override
            public OffsetDateTime deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JsonProcessingException {
                String value = jsonParser.getText();
                return Converter.parseDateTimeString(value);
            }
        });
        mapper.registerModule(module);
        LabelsReader = mapper.readerFor(new TypeReference<List<String>>() {});
        LabelsWriter = mapper.writerFor(new TypeReference<List<String>>() {});
    }

    private static ObjectReader getLabelsObjectReader() {
        if (LabelsReader == null) instantiateLabelsMapper();
        return LabelsReader;
    }

    private static ObjectWriter getLabelsObjectWriter() {
        if (LabelsWriter == null) instantiateLabelsMapper();
        return LabelsWriter;
    }

    private static ObjectReader StatusReader;
    private static ObjectWriter StatusWriter;

    private static void instantiateStatusMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.findAndRegisterModules();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
        mapper.configure(DeserializationFeature.ACCEPT_FLOAT_AS_INT, false);
        mapper.configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);
        SimpleModule module = new SimpleModule();
        module.addDeserializer(OffsetDateTime.class, new JsonDeserializer<OffsetDateTime>() {
            @Override
            public OffsetDateTime deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JsonProcessingException {
                String value = jsonParser.getText();
                return Converter.parseDateTimeString(value);
            }
        });
        mapper.registerModule(module);
        StatusReader = mapper.readerFor(Status.class);
        StatusWriter = mapper.writerFor(Status.class);
    }

    private static ObjectReader getStatusObjectReader() {
        if (StatusReader == null) instantiateStatusMapper();
        return StatusReader;
    }

    private static ObjectWriter getStatusObjectWriter() {
        if (StatusWriter == null) instantiateStatusMapper();
        return StatusWriter;
    }
}

package io.quicktype;

import com.fasterxml.jackson.annotation.*;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.OffsetTime;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * The kitchen sink.
 * Second line.
 */
public class TopLevel {
    private long empty;
    private Object anything;
    private OffsetTime at;
    private Map<String, Point> byName;
    private OffsetDateTime created;
    private List<OffsetDateTime> dates;
    private LocalDate day;
    private Empty topLevelEmpty;
    private Map<String, Empty> emptyMap;
    private Double topLevelFooBar;
    private String fooBar;
    private UUID id;
    private boolean isActive;
    private Kind kind;
    private OffsetTime maybeAt;
    private OffsetDateTime maybeCreated;
    private LocalDate maybeDay;
    private List<List<Nested>> nested;
    private Object nothing;
    private Numbers numbers;
    private OnlyDouble onlyDouble;
    private List<Point> points;
    private Stringish stringish;
    private String userURL;
    private Map<String, UUID> uuids;
    private WithEnumUnion withEnum;
    private WithMap withMap;
    private WithObject withObject;
    private WithString withString;

    @JsonAnyGetter
    public java.util.Map<String, Object> getEmpty() { return java.util.Collections.<String, Object>singletonMap("", empty); }
    @JsonAnySetter
    public void setEmpty(String key, long value) { if (key.isEmpty()) this.empty = value; }

    @JsonProperty("anything")
    public Object getAnything() { return anything; }
    @JsonProperty("anything")
    public void setAnything(Object value) { this.anything = value; }

    @JsonProperty("at")
    public OffsetTime getAt() { return at; }
    @JsonProperty("at")
    public void setAt(OffsetTime value) { this.at = value; }

    @JsonProperty("byName")
    public Map<String, Point> getByName() { return byName; }
    @JsonProperty("byName")
    public void setByName(Map<String, Point> value) { this.byName = value; }

    /**
     * When it was made.
     */
    @JsonProperty("created")
    public OffsetDateTime getCreated() { return created; }
    @JsonProperty("created")
    @JsonSetter(nulls = Nulls.FAIL)
    public void setCreated(OffsetDateTime value) { this.created = value; }

    @JsonProperty("dates")
    public List<OffsetDateTime> getDates() { return dates; }
    @JsonProperty("dates")
    public void setDates(List<OffsetDateTime> value) { this.dates = value; }

    @JsonProperty("day")
    public LocalDate getDay() { return day; }
    @JsonProperty("day")
    public void setDay(LocalDate value) { this.day = value; }

    @JsonProperty("empty")
    public Empty getTopLevelEmpty() { return topLevelEmpty; }
    @JsonProperty("empty")
    public void setTopLevelEmpty(Empty value) { this.topLevelEmpty = value; }

    @JsonProperty("emptyMap")
    public Map<String, Empty> getEmptyMap() { return emptyMap; }
    @JsonProperty("emptyMap")
    public void setEmptyMap(Map<String, Empty> value) { this.emptyMap = value; }

    @JsonProperty("foo_bar")
    public Double getTopLevelFooBar() { return topLevelFooBar; }
    @JsonProperty("foo_bar")
    public void setTopLevelFooBar(Double value) { this.topLevelFooBar = value; }

    @JsonProperty("fooBar")
    public String getFooBar() { return fooBar; }
    @JsonProperty("fooBar")
    public void setFooBar(String value) { this.fooBar = value; }

    @JsonProperty("id")
    public UUID getID() { return id; }
    @JsonProperty("id")
    public void setID(UUID value) { this.id = value; }

    @JsonProperty("isActive")
    public boolean getIsActive() { return isActive; }
    @JsonProperty("isActive")
    public void setIsActive(boolean value) { this.isActive = value; }

    /**
     * The kind.
     */
    @JsonProperty("kind")
    public Kind getKind() { return kind; }
    @JsonProperty("kind")
    public void setKind(Kind value) { this.kind = value; }

    @JsonProperty("maybeAt")
    public OffsetTime getMaybeAt() { return maybeAt; }
    @JsonProperty("maybeAt")
    public void setMaybeAt(OffsetTime value) { this.maybeAt = value; }

    @JsonProperty("maybeCreated")
    public OffsetDateTime getMaybeCreated() { return maybeCreated; }
    @JsonProperty("maybeCreated")
    public void setMaybeCreated(OffsetDateTime value) { this.maybeCreated = value; }

    @JsonProperty("maybeDay")
    public LocalDate getMaybeDay() { return maybeDay; }
    @JsonProperty("maybeDay")
    public void setMaybeDay(LocalDate value) { this.maybeDay = value; }

    @JsonProperty("nested")
    public List<List<Nested>> getNested() { return nested; }
    @JsonProperty("nested")
    public void setNested(List<List<Nested>> value) { this.nested = value; }

    @JsonProperty("nothing")
    public Object getNothing() { return nothing; }
    @JsonProperty("nothing")
    public void setNothing(Object value) { this.nothing = value; }

    @JsonProperty("numbers")
    public Numbers getNumbers() { return numbers; }
    @JsonProperty("numbers")
    public void setNumbers(Numbers value) { this.numbers = value; }

    @JsonProperty("onlyDouble")
    public OnlyDouble getOnlyDouble() { return onlyDouble; }
    @JsonProperty("onlyDouble")
    public void setOnlyDouble(OnlyDouble value) { this.onlyDouble = value; }

    @JsonProperty("points")
    public List<Point> getPoints() { return points; }
    @JsonProperty("points")
    public void setPoints(List<Point> value) { this.points = value; }

    @JsonProperty("stringish")
    public Stringish getStringish() { return stringish; }
    @JsonProperty("stringish")
    public void setStringish(Stringish value) { this.stringish = value; }

    @JsonProperty("userURL")
    public String getUserURL() { return userURL; }
    @JsonProperty("userURL")
    public void setUserURL(String value) { this.userURL = value; }

    @JsonProperty("uuids")
    public Map<String, UUID> getUuids() { return uuids; }
    @JsonProperty("uuids")
    public void setUuids(Map<String, UUID> value) { this.uuids = value; }

    @JsonProperty("withEnum")
    public WithEnumUnion getWithEnum() { return withEnum; }
    @JsonProperty("withEnum")
    public void setWithEnum(WithEnumUnion value) { this.withEnum = value; }

    @JsonProperty("withMap")
    public WithMap getWithMap() { return withMap; }
    @JsonProperty("withMap")
    public void setWithMap(WithMap value) { this.withMap = value; }

    @JsonProperty("withObject")
    public WithObject getWithObject() { return withObject; }
    @JsonProperty("withObject")
    public void setWithObject(WithObject value) { this.withObject = value; }

    @JsonProperty("withString")
    public WithString getWithString() { return withString; }
    @JsonProperty("withString")
    public void setWithString(WithString value) { this.withString = value; }
}

