}

package io.quicktype;

import java.io.IOException;
import com.fasterxml.jackson.annotation.*;

/**
 * The kind.
 */
public enum Kind {
    FIRST_KIND, SECOND, THIRD_KIND, DOLLAR, WITH_QUOTE;

    @JsonValue
    public String toValue() {
        switch (this) {
            case FIRST_KIND: return "first-kind";
            case SECOND: return "SECOND";
            case THIRD_KIND: return "third_kind";
            case DOLLAR: return "$dollar";
            case WITH_QUOTE: return "with \"quote\"";
        }
        return null;
    }

    @JsonCreator
    public static Kind forValue(String value) throws IOException {
        if (value.equals("first-kind")) return FIRST_KIND;
        if (value.equals("SECOND")) return SECOND;
        if (value.equals("third_kind")) return THIRD_KIND;
        if (value.equals("$dollar")) return DOLLAR;
        if (value.equals("with \"quote\"")) return WITH_QUOTE;
        throw new IOException("Cannot deserialize Kind");
    }
}

package io.quicktype;

import java.io.IOException;
import java.io.IOException;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.*;
import com.fasterxml.jackson.core.type.*;

@JsonDeserialize(using = Nested.Deserializer.class)
@JsonSerialize(using = Nested.Serializer.class)
public class Nested {
    public Long integerValue;
    public String stringValue;

    static class Deserializer extends JsonDeserializer<Nested> {
        @Override
        public Nested deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JsonProcessingException {
            Nested value = new Nested();
            switch (jsonParser.currentToken()) {
                case VALUE_NUMBER_INT:
                    value.integerValue = jsonParser.readValueAs(Long.class);
                    break;
                case VALUE_STRING:
                    String string = jsonParser.readValueAs(String.class);
                    value.stringValue = string;
                    break;
                default: throw new IOException("Cannot deserialize Nested");
            }
            return value;
        }
    }

    static class Serializer extends JsonSerializer<Nested> {
        @Override
        public void serialize(Nested obj, JsonGenerator jsonGenerator, SerializerProvider serializerProvider) throws IOException {
            if (obj.integerValue != null) {
                jsonGenerator.writeObject(obj.integerValue);
                return;
            }
            if (obj.stringValue != null) {
                jsonGenerator.writeObject(obj.stringValue);
                return;
            }
            throw new IOException("Nested must not be null");
        }
    }
}

