package io.quicktype;

import java.io.IOException;
import java.io.IOException;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.*;
import com.fasterxml.jackson.core.type.*;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.OffsetTime;
import java.util.UUID;

@JsonDeserialize(using = Stringish.Deserializer.class)
@JsonSerialize(using = Stringish.Serializer.class)
public class Stringish {
    public Long integerValue;
    public OffsetDateTime dateTimeValue;
    public LocalDate dateValue;
    public OffsetTime timeValue;
    public UUID uuidValue;

    static class Deserializer extends JsonDeserializer<Stringish> {
        @Override
        public Stringish deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JsonProcessingException {
            Stringish value = new Stringish();
            switch (jsonParser.currentToken()) {
                case VALUE_NUMBER_INT:
                    value.integerValue = jsonParser.readValueAs(Long.class);
                    break;
                case VALUE_STRING:
                    String string = jsonParser.readValueAs(String.class);
                    try {
                        value.uuidValue = UUID.fromString(string);
                    } catch (Exception ex) {
                        // Ignored
                    }
                    try {
                        value.timeValue = Converter.parseTimeString(string);
                    } catch (Exception ex) {
                        // Ignored
                    }
                    try {
                        value.dateValue = LocalDate.parse(string);
                    } catch (Exception ex) {
                        // Ignored
                    }
                    try {
                        value.dateTimeValue = Converter.parseDateTimeString(string);
                    } catch (Exception ex) {
                        // Ignored
                    }
                    break;
                default: throw new IOException("Cannot deserialize Stringish");
            }
            return value;
        }
    }

    static class Serializer extends JsonSerializer<Stringish> {
        @Override
        public void serialize(Stringish obj, JsonGenerator jsonGenerator, SerializerProvider serializerProvider) throws IOException {
            if (obj.integerValue != null) {
                jsonGenerator.writeObject(obj.integerValue);
                return;
            }
            if (obj.dateTimeValue != null) {
                jsonGenerator.writeObject(obj.dateTimeValue.format(java.time.format.DateTimeFormatter.ISO_OFFSET_DATE_TIME));
                return;
            }
            if (obj.dateValue != null) {
                jsonGenerator.writeObject(obj.dateValue.format(java.time.format.DateTimeFormatter.ISO_DATE));
                return;
            }
            if (obj.timeValue != null) {
                jsonGenerator.writeObject(obj.timeValue.format(java.time.format.DateTimeFormatter.ISO_OFFSET_TIME));
                return;
            }
            if (obj.uuidValue != null) {
                jsonGenerator.writeObject(obj.uuidValue);
                return;
            }
            throw new IOException("Stringish must not be null");
        }
    }
}

