@JsonDeserialize(using = WithMap.Deserializer.class)
@JsonSerialize(using = WithMap.Serializer.class)
public class WithMap {
    public Map<String, Long> integerMapValue;
    public String stringValue;

    static class Deserializer extends JsonDeserializer<WithMap> {
        @Override
        public WithMap deserialize(JsonParser jsonParser, DeserializationContext deserializationContext) throws IOException, JsonProcessingException {
            WithMap value = new WithMap();
